MOD = 998244353
MAX = int(4e5) + 10

factorialCache = [0] * MAX
inverseFactorialCache = [0] * MAX

def prepare():
    factorialCache[0] = 1
    inverseFactorialCache[0] = 1
    for i in range(1, MAX):
        factorialCache[i] = (factorialCache[i - 1] * i) % MOD
        inverseFactorialCache[i] = (inverseFactorialCache[i - 1] * modInverse(i, MOD)) % MOD

def computeNCr(n, r):
    return (factorialCache[n] * inverseFactorialCache[r] % MOD) * inverseFactorialCache[n - r] % MOD

def powerMod(base, exp):
    res = 1
    b = base % MOD
    e = exp
    while e > 0:
        if e & 1:
            res = (res * b) % MOD
        b = (b * b) % MOD
        e >>= 1
    return res

def extendedEuclidean(a, b):
    if a == 0:
        return (b, 0, 1)
    g, y, x = extendedEuclidean(b % a, a)
    return (g, x - (b // a) * y, y)

def modInverse(a, m):
    g, x, y = extendedEuclidean(a, m)
    if g != 1:
        return -1
    return (x % m + m) % m

