        temp = computeNCr(remaining, i)
        temp = (temp * powerMod(remaining - i, n)) % MOD
        if i & 1:
            totalSum -= temp
            if totalSum < 0:
                totalSum += MOD
        else:
            totalSum += temp
            if totalSum >= MOD:
                totalSum -= MOD
